import sys
from collections import deque

def solve():
    input = sys.stdin.read().split()
    ptr = 0
    t = int(input[ptr])
    ptr += 1
    for _ in range(t):
        n, m = map(int, input[ptr:ptr+2])
        ptr +=2
        adj = [[] for _ in range(n+1)]
        degree = [0]*(n+1)
        for __ in range(m):
            a, b = map(int, input[ptr:ptr+2])
            ptr +=2
            adj[a].append(b)
            adj[b].append(a)
            degree[a] +=1
            degree[b] +=1
        found = False
        for mask in range(1, 1<<n):
            if bin(mask).count('1') >=2 and bin(mask).count('1') <n:
                new_degree = degree.copy()
                stolen = []
                for i in range(1, n+1):
                    if mask & (1<<(i-1)):
                        stolen.append(i)
                        for neighbor in adj[i]:
                            if not (mask & (1<<(neighbor-1))):
                                new_degree[neighbor] -=1
                valid = True
                for i in range(1, n+1):
                    if not (mask & (1<<(i-1))):
                        if new_degree[i] %3 != degree[i] %3:
                            valid = False
                            break
                if valid:
                    print("Yes")
                    print(len(stolen))
                    print(' '.join(map(str, stolen)))
                    found = True
                    break
        if not found:
            print("No")

solve()
